SELECT
LM.MULTI_SCHEME_ID  AS MULTI_SCHEME_ID 
, SCHEME.NAME AS SCHEME
, LM.ID || '-' || NVL(LM.AUDIT_TYPE, '-') || '-' || NVL(TO_CHAR(LM.LAST_MODIFIED_ON, 'YYYYMMDD-HH24MISS'), '-') AS ID
, LM.ID AS MANIFEST_ID
, LM.LOT_ITEM_ID AS LOT_ITEM_ID
, LM.ACTUAL_WEIGHT_KGS AS MANIFEST_WEIGHT_KG
, LM.ACTUAL_BLOCKS AS ACTUAL_BLOCKS
, LM.CARRIER AS CARRIER
, LM.CONSIGNMENT_NO AS CONSIGNMENT_NO
, LM.REGISTRATION_NO AS REGISTRATION_NO
, LM.TRANSPORT_UNIT_TYPE AS TRANSPORT_UNIT_TYPE
, LM.TRANSPORT_UNIT_COUNT AS TRANSPORT_UNIT_COUNT
, CASE WHEN LM.FINAL_MANIFEST = 1 THEN 'Yes' else 'No' end AS FINAL_MANIFEST
, LM.EMPTY_TRUCK_WEIGHT AS EMPTY_TRUCK_WEIGHT
, LM.EMPTY_CONTAINER_WEIGHT AS EMPTY_CONTAINER_WEIGHT
, LM.TOTAL_TRUCK_WEIGHT AS TOTAL_TRUCK_WEIGHT
, CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(LM.MANIFEST_DATE AS TIMESTAMP))  AS MANIFEST_DATE
, LAG(LM.LOT_ITEM_ID) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS LOT_ITEM_ID_PREV
, LAG(LM.ACTUAL_WEIGHT_KGS) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS MANIFEST_WEIGHT_KG_PREV
, LAG(LM.ACTUAL_BLOCKS) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS ACTUAL_BLOCKS_PREV
, LAG(LM.CARRIER) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS CARRIER_PREV
, LAG(LM.CONSIGNMENT_NO) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS CONSIGNMENT_NO_PREV
, LAG(LM.REGISTRATION_NO) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS REGISTRATION_NO_PREV
, LAG(LM.TRANSPORT_UNIT_TYPE) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS TRANSPORT_UNIT_TYPE_PREV
, LAG(LM.TRANSPORT_UNIT_COUNT) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS TRANSPORT_UNIT_COUNT_PREV
, LAG(CASE WHEN LM.FINAL_MANIFEST = 1 THEN 'Yes' ELSE 'No' END) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS FINAL_MANIFEST_PREV
, LAG(LM.EMPTY_TRUCK_WEIGHT) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS EMPTY_TRUCK_WEIGHT_PREV
, LAG(LM.EMPTY_CONTAINER_WEIGHT) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS EMPTY_CONTAINER_WEIGHT_PREV
, LAG(LM.TOTAL_TRUCK_WEIGHT) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS TOTAL_TRUCK_WEIGHT_PREV
, LAG(CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(LM.MANIFEST_DATE AS TIMESTAMP)) ) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) AS MANIFEST_DATE_PREV
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(LM.LOT_ITEM_ID), '-') = NVL(TO_CHAR(LAG(LM.LOT_ITEM_ID) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS LOT_ITEM_ID_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(LM.ACTUAL_WEIGHT_KGS), '-') = NVL(TO_CHAR(LAG(LM.ACTUAL_WEIGHT_KGS) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS MANIFEST_WEIGHT_KG_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(LM.ACTUAL_BLOCKS), '-') = NVL(TO_CHAR(LAG(LM.ACTUAL_BLOCKS) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS ACTUAL_BLOCKS_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(LM.CARRIER), '-') = NVL(TO_CHAR(LAG(LM.CARRIER) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS CARRIER_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(LM.CONSIGNMENT_NO), '-') = NVL(TO_CHAR(LAG(LM.CONSIGNMENT_NO) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS CONSIGNMENT_NO_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(LM.REGISTRATION_NO), '-') = NVL(TO_CHAR(LAG(LM.REGISTRATION_NO) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS REGISTRATION_NO_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(LM.TRANSPORT_UNIT_TYPE), '-') = NVL(TO_CHAR(LAG(LM.TRANSPORT_UNIT_TYPE) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS TRANSPORT_UNIT_TYPE_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(LM.TRANSPORT_UNIT_COUNT), '-') = NVL(TO_CHAR(LAG(LM.TRANSPORT_UNIT_COUNT) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS TRANSPORT_UNIT_COUNT_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(CASE WHEN LM.FINAL_MANIFEST = 1 THEN 'Yes' ELSE 'No' END), '-') = NVL(TO_CHAR(LAG(CASE WHEN LM.FINAL_MANIFEST = 1 THEN 'Yes' ELSE 'No' END) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS FINAL_MANIFEST_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(LM.EMPTY_TRUCK_WEIGHT), '-') = NVL(TO_CHAR(LAG(LM.EMPTY_TRUCK_WEIGHT) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS EMPTY_TRUCK_WEIGHT_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(LM.EMPTY_CONTAINER_WEIGHT), '-') = NVL(TO_CHAR(LAG(LM.EMPTY_CONTAINER_WEIGHT) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS EMPTY_CONTAINER_WEIGHT_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(LM.TOTAL_TRUCK_WEIGHT), '-') = NVL(TO_CHAR(LAG(LM.TOTAL_TRUCK_WEIGHT) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS TOTAL_TRUCK_WEIGHT_ADJUST_FLAG
, CASE WHEN ROW_NUMBER() OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON) = 1 OR NVL(TO_CHAR(CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(LM.MANIFEST_DATE AS TIMESTAMP))), '-') = NVL(TO_CHAR(LAG(CONVERT_TIMEZONE('UTC',SCHEME.TIMEZONE,CAST(LM.MANIFEST_DATE AS TIMESTAMP)) ) OVER (PARTITION BY LM.ID ORDER BY LM.LAST_MODIFIED_ON)), '-') THEN 0 ELSE 1 END AS MANIFEST_DATE_ADJUST_FLAG
, LM.NOTE AS NOTE
, LM.MANIFEST_DATE AS MANIFEST_DATE_UTC
, LM.AUDIT_TYPE AS AUDIT_TYPE
, LM.AUDIT_DATE AS AUDIT_DATE
, LM.AUDIT_USER AS AUDIT_USER
, LM.LAST_MODIFIED_BY AS LAST_MODIFIED_BY
, LM.LAST_MODIFIED_ON AS LAST_MODIFIED_ON_UTC
, SYSDATE() AS INSERT_DATE_UTC
FROM
{{ source('CES_MSCM', 'LOT_ITEM_MANIFEST_A') }} AS LM
INNER JOIN {{ source('CES_MSCM', 'SCHEME') }} AS SCHEME
ON LM.MULTI_SCHEME_ID = SCHEME.MULTI_SCHEME_ID